sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.initials = function(name) {
    if (!name) return "S";

    var parts = name.trim().split(/\s+/);
    var result = parts[0].charAt(0);

    if (parts.length > 1) {
      result += parts[parts.length - 1].charAt(0);
    }

    return result.toUpperCase();
  };
};

sp_widget.css:
/* =========================================
   CAMPUSOPS STUDENT PROFILE
   Lavender theme + compact scrollable history
   ========================================= */

.co-profile {
  --cp-ink: #34264f;
  --cp-muted: #857992;
  --cp-purple: #8062c9;
  --cp-border: #e8dff3;
  width: 100%;
  color: var(--cp-ink);
  font-family: Inter, "Segoe UI", Arial, sans-serif;
  font-size: 12px;
  line-height: 1.55;
}

.co-profile * {
  box-sizing: border-box;
}

.co-profile a {
  text-decoration: none;
}

.co-profile a:focus-visible {
  outline: 2px solid #8062c9;
  outline-offset: 3px;
}

/* APP LAYOUT */

.co-profile .cp-layout {
  display: grid;
  grid-template-columns: 218px minmax(0, 1fr);
  align-items: stretch;
  gap: 25px;
  width: 100%;
}

.co-profile .cp-sidebar {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 690px;
  padding: 20px 13px;
  border: 1px solid #e9e0f5;
  border-radius: 19px;
  background: linear-gradient(180deg, #f8f4ff, #f3effb);
}

.co-profile .cp-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 7px 24px;
  color: #382b54;
}

.co-profile .cp-brand-mark {
  display: grid;
  place-items: center;
  width: 37px;
  height: 37px;
  flex-shrink: 0;
  border-radius: 11px;
  background: #8062c9;
  color: white;
  font-size: 19px;
  font-weight: 800;
}

.co-profile .cp-brand b {
  display: block;
  font-size: 14px;
  line-height: 1.3;
}

.co-profile .cp-brand small {
  display: block;
  margin-top: 4px;
  color: #8b7e9e;
  font-size: 9px;
}

.co-profile .cp-nav-label {
  padding: 9px 10px;
  color: #a092b6;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

.co-profile .cp-nav-gap {
  margin-top: 18px;
}

.co-profile .cp-nav {
  display: flex;
  align-items: center;
  gap: 11px;
  margin: 2px 0;
  padding: 11px 10px;
  border-radius: 10px;
  color: #6e6382;
  font-size: 11px;
  font-weight: 600;
  transition: background .18s, color .18s;
}

.co-profile .cp-nav > span {
  display: grid;
  place-items: center;
  width: 21px;
  flex-shrink: 0;
  color: #8d79b5;
  font-size: 16px;
}

.co-profile .cp-nav:hover {
  background: rgba(255,255,255,.8);
  color: #513a83;
}

.co-profile .cp-nav-active {
  background: #e8defa;
  color: #6245a0;
  font-weight: 750;
}

.co-profile .cp-sidebar-bottom {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: auto;
  padding: 18px 8px 3px;
  border-top: 1px solid #e4dbef;
}

.co-profile .cp-sidebar-bottom b {
  color: #59446f;
  font-size: 10px;
}

.co-profile .cp-sidebar-bottom small {
  color: #9386a5;
  font-size: 9px;
}

/* MAIN CONTENT */

.co-profile .cp-main {
  min-width: 0;
}

.co-profile .cp-breadcrumb {
  display: flex;
  gap: 9px;
  margin: 5px 0 20px;
  color: #a092b0;
  font-size: 10px;
}

.co-profile .cp-breadcrumb a {
  color: #8062c9;
}

/* PROFILE HEADER */

.co-profile .cp-hero {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 22px;
  overflow: hidden;
  padding: 26px;
  border: 1px solid rgba(255,255,255,.9);
  border-radius: 20px;
  background:
    radial-gradient(ellipse at 94% 0%, rgba(255,255,255,.85), transparent 38%),
    radial-gradient(ellipse at 0% 100%, rgba(218,201,255,.4), transparent 45%),
    linear-gradient(125deg, #f6f0ff, #eee5ff 52%, #fcecff);
  box-shadow: 0 12px 30px rgba(79,60,118,.06);
}

.co-profile .cp-hero-copy {
  min-width: 0;
  max-width: 650px;
}

.co-profile .cp-eyebrow {
  color: #927bb7;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

.co-profile .cp-hero h1 {
  margin: 7px 0 8px;
  color: #34264f;
  font-size: clamp(25px, 3vw, 35px);
  font-weight: 800;
  letter-spacing: -.8px;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.co-profile .cp-hero-copy > p {
  max-width: 470px;
  margin: 0;
  color: #82758f;
  font-size: 11px;
}

.co-profile .cp-user-email {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 19px;
}

.co-profile .cp-avatar {
  display: grid;
  place-items: center;
  width: 35px;
  height: 35px;
  flex-shrink: 0;
  border: 1px solid white;
  border-radius: 50%;
  background: rgba(255,255,255,.8);
  color: #7254ad;
  font-size: 11px;
  font-weight: 800;
}

.co-profile .cp-user-email b {
  display: block;
  color: #56436e;
  font-size: 10px;
}

.co-profile .cp-user-email small {
  display: block;
  margin-top: 2px;
  color: #9386a5;
  font-size: 9px;
  overflow-wrap: anywhere;
}

.co-profile .cp-hero-score {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 9px;
  flex-shrink: 0;
  padding: 0 14px;
}

.co-profile .cp-score-ring {
  display: grid;
  place-items: center;
  width: 98px;
  height: 98px;
  border-radius: 50%;
  box-shadow: 0 5px 15px rgba(89,66,132,.08);
}

.co-profile .cp-score-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 78%;
  height: 78%;
  border: 1px solid rgba(255,255,255,.95);
  border-radius: 50%;
  background: #fff;
}

.co-profile .cp-score-inner strong {
  color: #49365f;
  font-size: 25px;
  font-weight: 800;
  line-height: 1.2;
}

.co-profile .cp-score-inner span {
  margin-top: 3px;
  color: #9586a8;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .5px;
}

.co-profile .cp-score-caption {
  color: #927bb7;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .8px;
  text-align: center;
}

/* ATTENTION BANNER */

.co-profile .cp-attention {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 15px;
  padding: 14px 16px;
  border: 1px solid #f3d7a2;
  border-radius: 12px;
  background: #fff9ee;
}

.co-profile .cp-attention-mark {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border-radius: 9px;
  background: #ffedcf;
  color: #a96d20;
  font-size: 14px;
  font-weight: 800;
}

.co-profile .cp-attention-copy {
  min-width: 0;
  flex: 1;
}

.co-profile .cp-attention-copy b {
  color: #745329;
  font-size: 11px;
}

.co-profile .cp-attention-copy p {
  margin: 3px 0 0;
  color: #927954;
  font-size: 10px;
}

.co-profile .cp-attention > a {
  flex-shrink: 0;
  color: #986b29;
  font-size: 10px;
  font-weight: 750;
}

/* SECTION HEADINGS */

.co-profile .cp-section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin: 25px 0 13px;
}

.co-profile .cp-section-heading h2 {
  margin: 5px 0 0;
  color: #38294f;
  font-size: 19px;
  font-weight: 800;
  letter-spacing: -.3px;
}

.co-profile .cp-section-heading p {
  margin: 4px 0 0;
  color: #8b7e99;
  font-size: 10px;
}

.co-profile .cp-risk-pill {
  flex-shrink: 0;
  padding: 5px 9px;
  border-radius: 20px;
  background: #eaf7ef;
  color: #4c956f;
  font-size: 8px;
  font-weight: 800;
}

.co-profile .cp-risk-medium {
  background: #fff2d9;
  color: #a66d25;
}

.co-profile .cp-risk-high {
  background: #ffeaed;
  color: #bc5267;
}

/* RELIABILITY SUMMARY */

.co-profile .cp-summary-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(190px, 1fr);
  gap: 13px;
}

.co-profile .cp-reliability-card {
  display: flex;
  align-items: center;
  gap: 17px;
  min-width: 0;
  padding: 19px;
  border: 1px solid #e7ddf4;
  border-radius: 15px;
  background: linear-gradient(135deg, #fff, #faf6ff);
  box-shadow: 0 4px 14px rgba(79,60,118,.025);
}

.co-profile .cp-score-ring-large {
  width: 91px;
  height: 91px;
  flex-shrink: 0;
}

.co-profile .cp-score-ring-large .cp-score-inner strong {
  font-size: 23px;
}

.co-profile .cp-reliability-copy {
  min-width: 0;
  flex: 1;
}

.co-profile .cp-reliability-copy h3 {
  margin: 5px 0;
  color: #49365f;
  font-size: 13px;
  font-weight: 800;
}

.co-profile .cp-reliability-copy p {
  margin: 0;
  color: #877a94;
  font-size: 10px;
  line-height: 1.7;
}

.co-profile .cp-progress-track {
  overflow: hidden;
  height: 5px;
  margin-top: 13px;
  border-radius: 10px;
  background: #eae3f4;
}

.co-profile .cp-progress-track span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #8062c9;
  transition: width .3s ease;
}

.co-profile .cp-reliability-copy > small {
  display: block;
  margin-top: 5px;
  color: #9b8ead;
  font-size: 9px;
  text-align: right;
}

.co-profile .cp-stat-stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.co-profile .cp-stat-card {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 1;
  padding: 11px;
  border: 1px solid #e8dff3;
  border-radius: 12px;
  background: rgba(255,255,255,.85);
}

.co-profile .cp-stat-mark {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  flex-shrink: 0;
  border-radius: 9px;
  background: #efe7ff;
  color: #8062c9;
  font-size: 13px;
  font-weight: 800;
}

.co-profile .cp-stat-green {
  background: #e7f6ed;
  color: #4b9a71;
}

.co-profile .cp-stat-orange {
  background: #fff0df;
  color: #bd8142;
}

.co-profile .cp-stat-card > div {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.co-profile .cp-stat-card small {
  color: #9586a8;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .4px;
}

.co-profile .cp-stat-card strong {
  margin: 1px 0;
  color: #443254;
  font-size: 17px;
  font-weight: 800;
  line-height: 1.3;
}

.co-profile .cp-stat-card > div > span {
  color: #978ba3;
  font-size: 8px;
}

/* BORROWING HISTORY SECTION */

.co-profile .cp-history {
  margin-top: 28px;
}

.co-profile .cp-history .cp-section-heading {
  margin-top: 0;
}

.co-profile .cp-outline-link {
  flex-shrink: 0;
  padding: 8px 11px;
  border: 1px solid #dfd2f2;
  border-radius: 9px;
  background: #fff;
  color: #7959b8;
  font-size: 9px;
  font-weight: 750;
  transition: background .15s;
}

.co-profile .cp-outline-link:hover {
  background: #f5efff;
}

/* FIXED-HEIGHT INTERNAL SCROLL AREA */

.co-profile .cp-timeline {
  position: relative;
  max-height: 430px;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 10px 12px 8px 22px;
  border: 1px solid #e7ddf4;
  border-radius: 14px;
  background: rgba(255,255,255,.58);
  scrollbar-width: thin;
  scrollbar-color: #c7b5e8 #f5f0fb;
  overscroll-behavior: contain;
}

/* Timeline line stays inside the scroll panel */

.co-profile .cp-timeline:before {
  position: absolute;
  top: 10px;
  bottom: 10px;
  left: 6px;
  width: 2px;
  background: linear-gradient(#b39be8, #e8dff5);
  content: "";
}

/* RENTAL ENTRIES */

.co-profile .cp-timeline-entry {
  position: relative;
  margin-bottom: 9px;
}

.co-profile .cp-timeline-entry:last-child {
  margin-bottom: 0;
}

.co-profile .cp-timeline-marker {
  position: absolute;
  top: 18px;
  left: -21px;
  z-index: 1;
  width: 12px;
  height: 12px;
  border: 3px solid #f5f0ff;
  border-radius: 50%;
  background: #8c6bd0;
  box-shadow: 0 0 0 1px #c9b8eb;
}

.co-profile .cp-entry-returned .cp-timeline-marker {
  background: #59a980;
  box-shadow: 0 0 0 1px #b7e3c9;
}

.co-profile .cp-entry-overdue .cp-timeline-marker {
  background: #d86b7d;
  box-shadow: 0 0 0 1px #f1c0c8;
}

.co-profile .cp-entry-due .cp-timeline-marker {
  background: #d69a45;
  box-shadow: 0 0 0 1px #f1d4a6;
}

.co-profile .cp-timeline-card {
  padding: 12px 14px;
  border: 1px solid #e7ddf4;
  border-radius: 12px;
  background: rgba(255,255,255,.95);
  transition: border-color .18s, box-shadow .18s;
}

.co-profile .cp-timeline-card:hover {
  border-color: #cdb9ed;
  box-shadow: 0 4px 12px rgba(79,60,118,.07);
}

.co-profile .cp-rental-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.co-profile .cp-rental-type {
  color: #9a8aaf;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .7px;
  text-transform: uppercase;
}

.co-profile .cp-rental-top h3 {
  margin: 4px 0 2px;
  color: #49365f;
  font-size: 12px;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.co-profile .cp-rental-top p {
  margin: 0;
  color: #9a8ca8;
  font-size: 9px;
}

.co-profile .cp-status-pill {
  flex-shrink: 0;
  padding: 5px 8px;
  border-radius: 20px;
  background: #eaf7ef;
  color: #4b956e;
  font-size: 8px;
  font-weight: 800;
}

.co-profile .cp-status-overdue {
  background: #ffeaed;
  color: #ba5368;
}

.co-profile .cp-status-due {
  background: #fff2dc;
  color: #a86c24;
}

.co-profile .cp-status-returned {
  background: #f0eaff;
  color: #7959b8;
}

.co-profile .cp-rental-details {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-top: 11px;
  padding: 10px 0;
  border-top: 1px solid #f0eaf7;
  border-bottom: 1px solid #f0eaf7;
}

.co-profile .cp-rental-details > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.co-profile .cp-rental-details span {
  color: #9a8aaf;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .3px;
}

.co-profile .cp-rental-details strong {
  color: #5b496e;
  font-size: 9px;
  font-weight: 650;
  overflow-wrap: anywhere;
}

.co-profile .cp-rental-note {
  margin-top: 9px;
  color: #b85c6d;
  font-size: 9px;
}

.co-profile .cp-note-returned {
  color: #4b956e;
}

.co-profile .cp-rental-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 9px;
}

.co-profile .cp-rental-bottom > span {
  color: #9a8ca8;
  font-size: 8px;
  overflow-wrap: anywhere;
}

.co-profile .cp-rental-bottom a {
  flex-shrink: 0;
  color: #7959b8;
  font-size: 9px;
  font-weight: 750;
}

/* SCROLLBAR */

.co-profile .cp-timeline::-webkit-scrollbar {
  width: 7px;
}

.co-profile .cp-timeline::-webkit-scrollbar-track {
  background: #f5f0fb;
  border-radius: 10px;
}

.co-profile .cp-timeline::-webkit-scrollbar-thumb {
  background: #c7b5e8;
  border: 2px solid #f5f0fb;
  border-radius: 10px;
}

.co-profile .cp-timeline::-webkit-scrollbar-thumb:hover {
  background: #a58ad8;
}

/* EMPTY HISTORY */

.co-profile .cp-empty {
  padding: 28px 20px;
  border: 1px solid #e7ddf4;
  border-radius: 14px;
  background: #fff;
  text-align: center;
}

.co-profile .cp-empty h3 {
  margin: 0;
  color: #49365f;
  font-size: 14px;
}

.co-profile .cp-empty p {
  margin: 8px 0 15px;
  color: #897d99;
  font-size: 10px;
}

.co-profile .cp-empty a {
  display: inline-block;
  padding: 9px 13px;
  border-radius: 9px;
  background: #8062c9;
  color: white;
  font-size: 10px;
  font-weight: 750;
}

/* FOOTER */

.co-profile .cp-footer {
  margin-top: 28px;
  padding: 17px 2px 5px;
  border-top: 1px solid #e9e2f1;
}

.co-profile .cp-footer-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.co-profile .cp-footer-top b {
  color: #55416f;
  font-size: 11px;
}

.co-profile .cp-footer-top p {
  margin: 4px 0 0;
  color: #988ca8;
  font-size: 9px;
}

.co-profile .cp-footer-top > a {
  color: #7959b8;
  font-size: 10px;
  font-weight: 750;
}

.co-profile .cp-footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 13px;
}

.co-profile .cp-footer-links a {
  color: #796a8d;
  font-size: 10px;
}

.co-profile .cp-footer-links a:hover {
  color: #6748a8;
}

.co-profile .cp-footer-copy {
  margin-top: 12px;
  color: #a399b1;
  font-size: 9px;
}

/* RESPONSIVE TABLET */

@media (max-width: 1000px) {
  .co-profile .cp-layout {
    grid-template-columns: 185px minmax(0, 1fr);
    gap: 16px;
  }

  .co-profile .cp-sidebar {
    padding: 15px 9px;
  }

  .co-profile .cp-summary-grid {
    grid-template-columns: 1fr;
  }

  .co-profile .cp-stat-stack {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .co-profile .cp-stat-card {
    align-items: flex-start;
  }
}

/* RESPONSIVE MOBILE */

@media (max-width: 680px) {
  .co-profile .cp-layout {
    grid-template-columns: 1fr;
    gap: 18px;
  }

  .co-profile .cp-sidebar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-content: start;
    gap: 3px;
    min-height: 0;
    padding: 12px;
  }

  .co-profile .cp-brand {
    grid-column: 1 / -1;
    padding-bottom: 12px;
  }

  .co-profile .cp-nav-label,
  .co-profile .cp-sidebar-bottom {
    display: none;
  }

  .co-profile .cp-nav {
    margin: 0;
    padding: 10px 8px;
  }

  .co-profile .cp-hero {
    align-items: flex-start;
    flex-direction: column;
    padding: 20px;
  }

  .co-profile .cp-hero-score {
    align-self: center;
    padding-top: 8px;
  }

  .co-profile .cp-attention {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .co-profile .cp-attention > a {
    margin-left: 42px;
  }

  .co-profile .cp-section-heading h2 {
    font-size: 17px;
  }

  .co-profile .cp-reliability-card {
    align-items: flex-start;
    flex-direction: column;
  }

  .co-profile .cp-stat-stack {
    grid-template-columns: 1fr;
  }

  .co-profile .cp-rental-details {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .co-profile .cp-timeline {
    max-height: 360px;
    padding-right: 8px;
  }

  .co-profile .cp-footer-top {
    flex-direction: column;
  }
}



/* CLEANER BORROWING TIMELINE */

.co-profile .cp-timeline {
  position: relative;
  max-height: 540px;
  overflow-y: auto;
  overflow-x: hidden;

  /* Remove the cramped outer panel */
  padding: 6px 10px 6px 22px;
  border: none;
  border-radius: 0;
  background: transparent;
  box-shadow: none;

  /* Slim scrollbar on the right */
  scrollbar-width: thin;
  scrollbar-color: #c7b5e8 transparent;
  overscroll-behavior: contain;
}

/* Keep the timeline line and markers */
.co-profile .cp-timeline:before {
  position: absolute;
  top: 8px;
  bottom: 8px;
  left: 6px;
  width: 2px;
  background: linear-gradient(#b39be8, #e8dff5);
  content: "";
}

/* More compact cards */
.co-profile .cp-timeline-entry {
  position: relative;
  margin-bottom: 8px;
}

.co-profile .cp-timeline-entry:last-child {
  margin-bottom: 0;
}

.co-profile .cp-timeline-card {
  padding: 10px 12px;
  border: 1px solid #e7ddf4;
  border-radius: 10px;
  background: rgba(255, 255, 255, .82);
  box-shadow: none;
  transition: border-color .18s, background .18s;
}

.co-profile .cp-timeline-card:hover {
  transform: none;
  border-color: #cdb9ed;
  background: #fff;
  box-shadow: none;
}

/* Reduce space inside each rental card */
.co-profile .cp-rental-details {
  gap: 8px;
  margin-top: 8px;
  padding: 8px 0;
}

.co-profile .cp-rental-bottom {
  margin-top: 7px;
}

/* Hide scrollbar track; retain right-side thumb */
.co-profile .cp-timeline::-webkit-scrollbar {
  width: 6px;
}

.co-profile .cp-timeline::-webkit-scrollbar-track {
  background: transparent;
}

.co-profile .cp-timeline::-webkit-scrollbar-thumb {
  background: #c7b5e8;
  border-radius: 10px;
}

.co-profile .cp-timeline::-webkit-scrollbar-thumb:hover {
  background: #a58ad8;
}

/* Mobile layout */
@media (max-width: 680px) {
  .co-profile .cp-timeline {
    max-height: 420px;
    padding-right: 6px;
  }

  .co-profile .cp-timeline-card {
    padding: 10px;
  }

  .co-profile .cp-rental-details {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}



/* CAMPUSOPS PROFILE — TYPOGRAPHY CONSISTENCY */

.co-profile {
  font-family: "Inter", "Segoe UI", Arial, sans-serif;
  font-size: 13px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* Consistent body text */
.co-profile p,
.co-profile small,
.co-profile .cp-nav,
.co-profile .cp-breadcrumb,
.co-profile .cp-rental-details strong,
.co-profile .cp-footer-links a {
  font-family: inherit;
}

/* Match navigation typography */
.co-profile .cp-nav {
  font-size: 12px;
  font-weight: 500;
  line-height: 1.5;
  letter-spacing: 0;
}

.co-profile .cp-nav-active {
  font-weight: 650;
}

/* Match the CampusOps brand */
.co-profile .cp-brand b {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.2px;
}

.co-profile .cp-brand small {
  font-size: 10px;
}

/* Match page headings */
.co-profile .cp-hero h1 {
  font-size: clamp(26px, 2.5vw, 34px);
  font-weight: 750;
  letter-spacing: -0.7px;
  line-height: 1.2;
}

.co-profile .cp-section-heading h2 {
  font-size: 20px;
  font-weight: 750;
  letter-spacing: -0.35px;
}

/* Keep card headings consistent */
.co-profile .cp-rental-top h3,
.co-profile .cp-reliability-copy h3 {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: -0.1px;
}

/* Improve readability of supporting text */
.co-profile .cp-hero-copy > p,
.co-profile .cp-attention-copy p,
.co-profile .cp-reliability-copy p,
.co-profile .cp-section-heading p {
  font-size: 11px;
  line-height: 1.6;
}

/* Consistent breadcrumb and footer text */
.co-profile .cp-breadcrumb {
  font-size: 11px;
}

.co-profile .cp-footer-links a,
.co-profile .cp-footer-top > a {
  font-size: 11px;
}

sp_widget.script:
(function() {
  data.user = {
    name: gs.getUserDisplayName(),
    email: gs.getUser().getEmail()
  };

  data.rentals = [];
  data.dueSoon = [];
  data.stats = {
    total: 0,
    active: 0,
    returned: 0,
    overdue: 0
  };

  data.score = 100;
  data.riskLabel = "LOW";
  data.riskClass = "low";
  data.scoreMessage = "A promising start";
  data.scoreExplanation =
    "Keep returning resources on time to build a strong borrowing record.";

  var userId = gs.getUserID();
  var now = new GlideDateTime().getNumericValue();
  var totalScore = 0;
  var scoredRentals = 0;

  var rental = new GlideRecord("u_student_rental");
  rental.addQuery("u_student", userId);
  rental.orderByDesc("u_rental_date");
  rental.query();

  function fmt(value) {
    if (!value) return "";

    var date = new GlideDateTime(value);
    return date.getLocalDate().getByFormat("dd MMM yyyy");
  }

  while (rental.next()) {
    data.stats.total++;

    var status = (rental.getValue("u_status") || "").toLowerCase();
    var dueValue = rental.getValue("u_due_date");
    var returnValue = rental.getValue("u_return_date");
    var overdue = false;

    if (status === "returned") {
      data.stats.returned++;
    } else if (status === "active") {
      data.stats.active++;

      if (dueValue &&
          new GlideDateTime(dueValue).getNumericValue() < now) {
        overdue = true;
        data.stats.overdue++;
      }
    }

    // Include every rental that has a valid reliability score.
    var scoreValue = rental.getValue("u_reliability_score");

    if (scoreValue !== null && scoreValue !== "") {
      var parsedScore = parseInt(scoreValue, 10);

      if (!isNaN(parsedScore)) {
        totalScore += Math.max(0, Math.min(100, parsedScore));
        scoredRentals++;
      }
    }

    var risk = (rental.getValue("u_return_risk") || "").toLowerCase();
    var riskLabel = risk
      ? risk.charAt(0).toUpperCase() + risk.substring(1)
      : "Not assessed";

    var daysLeft = null;

    if (dueValue) {
      daysLeft = Math.ceil(
        (new GlideDateTime(dueValue).getNumericValue() - now) /
        86400000
      );
    }

    var statusClass = status === "returned"
      ? "returned"
      : (overdue ? "overdue" : "active");

    var statusLabel = overdue
      ? "Overdue"
      : (status === "returned"
          ? "Returned"
          : (status === "active" && daysLeft !== null && daysLeft <= 2
              ? "Due Soon"
              : "Active"));

    var assetName = rental.getDisplayValue("u_asset") || "Campus resource";
    var assetType = "";
    var location = "";

    var asset = rental.u_asset.getRefRecord();

    if (asset && asset.isValidRecord()) {
      assetType = asset.getDisplayValue("u_asset_type") || "";
      location = asset.getDisplayValue("u_location") || "";
    }

    var entry = {
      id: rental.getUniqueValue(),
      assetName: assetName,
      assetType: assetType,
      location: location,
      rentalDate: fmt(rental.getValue("u_rental_date")),
      dueDate: fmt(dueValue),
      returnDate: fmt(returnValue),
      statusClass: statusClass,
      statusLabel: statusLabel,
      riskLabel: riskLabel,
      message: overdue
        ? "This item is overdue."
        : "Its return date is approaching."
    };

    data.rentals.push(entry);

    if (status === "active" && dueValue && daysLeft <= 2) {
      data.dueSoon.push(entry);
    }
  }

  // Calculate the average across all scored rental records.
  if (scoredRentals > 0) {
    data.score = Math.round(totalScore / scoredRentals);
  }

  // Derive the overall risk from the average score.
  if (data.score < 40) {
    data.riskLabel = "HIGH";
    data.riskClass = "high";
    data.scoreMessage = "Let's rebuild your record";
    data.scoreExplanation =
      "Prioritise overdue returns and keep your next due dates in sight.";
  } else if (data.score < 70) {
    data.riskLabel = "MEDIUM";
    data.riskClass = "medium";
    data.scoreMessage = "You're making progress";
    data.scoreExplanation =
      "A little more consistency with return dates will strengthen your score.";
  } else {
    data.riskLabel = "LOW";
    data.riskClass = "low";
    data.scoreMessage = "A reliable resource keeper";
    data.scoreExplanation =
      "Great work. Keep looking after borrowed resources and returning them on time.";
  }
})();
